"""Analyze the tracked Starlink Group 4-7 satellites from theFebruary 2022 geomagnetic-storm loss event.This script:1. Loads the Space-Track GP history downloaded by   download_starlink_2022.py.2. Converts mean motion into approximate orbital altitude.3. Calculates daily median altitude for each tracked satellite.4. Calculates altitude-change rates using the actual   time between daily observations.5. Summarizes the orbital evolution of each tracked satellite."""from pathlib import Pathimport jsonimport numpy as npimport pandas as pdfrom orbital_altitude import mean_motion_to_altitude_kmimport matplotlib.pyplot as plt# PathsPROJECT_ROOT = Path(__file__).resolve().parent.parentRAW_DATA_DIR = (    PROJECT_ROOT    / "data"    / "raw")PROCESSED_DATA_DIR = (    PROJECT_ROOT    / "data"    / "processed")RESULTS_DIR = (    PROJECT_ROOT    / "results")PROCESSED_DATA_DIR.mkdir(    parents=True,    exist_ok=True,)RESULTS_DIR.mkdir(    parents=True,    exist_ok=True,)INPUT_FILE = (    RAW_DATA_DIR    / "starlink_2022_group_4_7_gp_history.json")ORBITAL_OUTPUT_FILE = (    PROCESSED_DATA_DIR    / "starlink_2022_orbital_history.csv")DAILY_OUTPUT_FILE = (    PROCESSED_DATA_DIR    / "starlink_2022_daily_altitudes.csv")SUMMARY_OUTPUT_FILE = (    RESULTS_DIR    / "starlink_2022_satellite_summary.csv")SATCAT_FILE = (    RAW_DATA_DIR    / "starlink_2022_group_4_7_satcat.json")KP_DAILY_FILE = (    PROCESSED_DATA_DIR    / "kp_daily_2022-02-01_to_2022-02-15.csv")FIGURE_FILE = (    RESULTS_DIR    / "starlink_2022_altitude_kp.png")# Load Space-Track datadef load_orbital_history():    print(        "Loading Starlink orbital history from:"    )    print(        INPUT_FILE    )    if not INPUT_FILE.exists():        raise FileNotFoundError(            f"\nCould not find:\n"            f"{INPUT_FILE}\n\n"            f"Run download_starlink_2022.py first."        )    with open(        INPUT_FILE,        "r",        encoding="utf-8",    ) as file:        records = json.load(            file        )    print(        f"\nRaw orbital records loaded: "        f"{len(records)}"    )    return records# Process individual GP recordsdef process_orbital_records(    records,):    rows = []    for record in records:        try:            norad_id = int(                record[                    "NORAD_CAT_ID"                ]            )            object_id = record.get(                "OBJECT_ID",                "",            )            object_name = record.get(                "OBJECT_NAME",                "",            )            epoch = pd.to_datetime(                record[                    "EPOCH"                ],                errors="coerce",                utc=True,            )            mean_motion = float(                record[                    "MEAN_MOTION"                ]            )            eccentricity = float(                record.get(                    "ECCENTRICITY",                    np.nan,                )            )            inclination = float(                record.get(                    "INCLINATION",                    np.nan,                )            )            (                semi_major_axis_km,                altitude_km,            ) = mean_motion_to_altitude_km(                mean_motion            )            rows.append(                {                    "norad_id":                        norad_id,                    "object_id":                        object_id,                    "object_name":                        object_name,                    "epoch":                        epoch,                    "mean_motion_rev_day":                        mean_motion,                    "eccentricity":                        eccentricity,                    "inclination_deg":                        inclination,                    "semi_major_axis_km":                        semi_major_axis_km,                    "altitude_km":                        altitude_km,                }            )        except (            KeyError,            TypeError,            ValueError,        ) as error:            print(                f"Skipping invalid record: "                f"{error}"            )    df = pd.DataFrame(        rows    )    if df.empty:        raise ValueError(            "No valid Starlink orbital "            "records were produced."        )    df = df.dropna(        subset=[            "epoch",            "altitude_km",        ]    )    df = df.sort_values(        [            "norad_id",            "epoch",        ]    ).reset_index(        drop=True    )    df.to_csv(        ORBITAL_OUTPUT_FILE,        index=False,    )    print(        f"\nProcessed orbital observations: "        f"{len(df)}"    )    print(        f"\nSaved processed orbital history to:\n"        f"{ORBITAL_OUTPUT_FILE}"    )    return df# Daily median altitudedef calculate_daily_altitudes(    df,):    data = df.copy()    # Convert every observation timestamp    # to its UTC calendar day.    data["date"] = (        data["epoch"]        .dt.floor("D")    )    daily = (        data.groupby(            [                "norad_id",                "object_id",                "date",            ],            as_index=False,        )["altitude_km"]        .median()        .rename(            columns={                "altitude_km":                    "daily_median_altitude_km"            }        )    )    daily = daily.sort_values(        [            "norad_id",            "date",        ]    ).reset_index(        drop=True    )    # Actual time between daily observations    daily[        "time_difference_days"    ] = (        daily.groupby(            "norad_id"        )["date"]        .diff()        .dt.total_seconds()        / 86400.0    )    # Altitude change      daily[        "altitude_change_km"    ] = (        daily.groupby(            "norad_id"        )[            "daily_median_altitude_km"        ]        .diff()    )       # Altitude change rate        # Positive = altitude increased    # Negative = altitude decreased    daily[        "altitude_change_rate_km_day"    ] = (        daily[            "altitude_change_km"        ]        /        daily[            "time_difference_days"        ]    )    # Orbital decay rate        # Positive number = downward motion    daily[        "orbital_decay_km_day"    ] = (        -daily[            "altitude_change_rate_km_day"        ]    )    # Remove invalid elapsed-time cases    daily.loc[        daily[            "time_difference_days"        ] <= 0,        [            "altitude_change_rate_km_day",            "orbital_decay_km_day",        ],    ] = np.nan    daily.to_csv(        DAILY_OUTPUT_FILE,        index=False,    )    print(        f"\nDaily satellite observations: "        f"{len(daily)}"    )    print(        f"\nSaved daily altitude data to:\n"        f"{DAILY_OUTPUT_FILE}"    )    return dailydef load_satcat_data():    """    Load Space-Track catalog information for the    17 tracked Starlink Group 4-7 payloads.    """    if not SATCAT_FILE.exists():        raise FileNotFoundError(            f"\nCould not find:\n"            f"{SATCAT_FILE}\n\n"            f"Run download_starlink_2022.py first."        )    with open(        SATCAT_FILE,        "r",        encoding="utf-8",    ) as file:        records = json.load(file)    satcat = pd.DataFrame(        records    )    satcat["decay_date"] = pd.to_datetime(        satcat["decay_date"],        errors="coerce",        utc=True,    )    return satcatdef load_kp_data():    """    Load daily Kp values for the February 2022    Starlink case-study window.    """    if not KP_DAILY_FILE.exists():        raise FileNotFoundError(            f"\nCould not find:\n"            f"{KP_DAILY_FILE}\n\n"            f"Run download_kp.py first."        )    kp = pd.read_csv(        KP_DAILY_FILE    )    kp["date"] = pd.to_datetime(        kp["date"],        errors="coerce",        utc=True,    )    return kpdef merge_kp_with_altitude(    daily,    kp,):    """    Merge daily satellite altitude data with    daily geomagnetic activity.    """    merged = daily.merge(        kp,        on="date",        how="left",    )    output_file = (        PROCESSED_DATA_DIR        / "starlink_2022_daily_altitude_kp.csv"    )    merged.to_csv(        output_file,        index=False,    )    print(        f"\nSaved Starlink altitude + Kp data to:\n"        f"{output_file}"    )    return merged# Satellite-level summarydef summarize_satellites(    daily,):    results = []    for norad_id, satellite in (        daily.groupby(            "norad_id"        )    ):        satellite = (            satellite            .sort_values(                "date"            )            .copy()        )        first = (            satellite.iloc[0]        )        last = (            satellite.iloc[-1]        )        first_date = (            first["date"]        )        last_date = (            last["date"]        )        tracking_duration_days = (            last_date            - first_date        ).days        initial_altitude_km = (            first[                "daily_median_altitude_km"            ]        )        final_altitude_km = (            last[                "daily_median_altitude_km"            ]        )        net_altitude_change_km = (            final_altitude_km            - initial_altitude_km        )        min_altitude_km = (            satellite[                "daily_median_altitude_km"            ]            .min()        )        max_altitude_km = (            satellite[                "daily_median_altitude_km"            ]            .max()        )        valid_decay = (            satellite[                "orbital_decay_km_day"            ]            .dropna()        )        if not valid_decay.empty:            mean_decay_km_day = (                valid_decay.mean()            )            positive_decay = (                valid_decay[                    valid_decay > 0                ]            )                        if not positive_decay.empty:                            max_decay_km_day = (                    positive_decay.max()                )                        else:                            max_decay_km_day = 0.0        else:            mean_decay_km_day = (                np.nan            )            max_decay_km_day = (                np.nan            )        # Count days on which altitude decreased        decay_days = (            satellite[                "orbital_decay_km_day"            ]            > 0        ).sum()        # Count days on which altitude increased,        # likely indicating orbit raising.        orbit_raise_days = (            satellite[                "altitude_change_rate_km_day"            ]            > 0        ).sum()        results.append(            {                "norad_id":                    norad_id,                "object_id":                    first[                        "object_id"                    ],                "first_date":                    first_date,                "last_date":                    last_date,                "tracking_duration_days":                    tracking_duration_days,                "daily_observations":                    len(                        satellite                    ),                "initial_altitude_km":                    initial_altitude_km,                "final_altitude_km":                    final_altitude_km,                "net_altitude_change_km":                    net_altitude_change_km,                "minimum_altitude_km":                    min_altitude_km,                "maximum_altitude_km":                    max_altitude_km,                "mean_orbital_decay_km_day":                    mean_decay_km_day,                "maximum_orbital_decay_km_day":                    max_decay_km_day,                "decay_days":                    decay_days,                "orbit_raise_days":                    orbit_raise_days,            }        )    summary = pd.DataFrame(        results    )    summary = summary.sort_values(        "norad_id"    ).reset_index(        drop=True    )    summary.to_csv(        SUMMARY_OUTPUT_FILE,        index=False,    )    return summarydef add_event_outcomes(    summary,    satcat,):    """    Merge catalog decay dates with the orbital summary    and consider whether each tracked satellite was lost    during the February 2022 event.       """    merged = summary.merge(        satcat[            [                "norad_id",                "satellite_name",                "decay_date",            ]        ],        on="norad_id",        how="left",    )    # Event-loss window.    #    # The launch occurred February 3, 2022.    # All tracked storm-associated losses in this    # dataset decayed by February 12.    event_end = pd.Timestamp(        "2022-02-15",        tz="UTC",    )    merged["event_outcome"] = np.where(        (            merged["decay_date"].notna()            &            (                merged["decay_date"]                <= event_end            )        ),        "EVENT_LOSS",        "SURVIVED_EVENT",    )    merged.to_csv(        SUMMARY_OUTPUT_FILE,        index=False,    )    return merged# Overall event summarydef print_event_summary(    summary,):    print(        "\n-----------------------------------"    )    print(        "STARLINK GROUP 4-7 CASE STUDY"    )    print(        "-----------------------------------"    )    print(        f"\nTracked Starlink payloads "        f"in Space-Track data: "        f"{len(summary)}"    )    print(        "\nSatellite orbital summaries:\n"    )    columns = [        "norad_id",        "object_id",        "satellite_name",        "tracking_duration_days",        "initial_altitude_km",        "final_altitude_km",        "net_altitude_change_km",        "maximum_orbital_decay_km_day",        "decay_date",        "event_outcome",    ]    print(        summary[            columns        ].to_string(            index=False        )    )    # Count satellites lost during the February 2022 event    event_losses = (        summary[            summary["event_outcome"]            == "EVENT_LOSS"        ]    )    # Count satellites that survived the event    survived = (        summary[            summary["event_outcome"]            == "SURVIVED_EVENT"        ]    )    print(        f"\nTracked satellites lost "        f"during event: "        f"{len(event_losses)}"    )    print(        f"Tracked satellites surviving "        f"event: "        f"{len(survived)}"    )    print(        "\nPublished/event totals:"    )    print(        "49 satellites launched"    )    print(        "32 satellites not tracked by NORAD"    )    print(        f"{len(event_losses)} tracked "        f"satellites lost during event"    )    total_losses = (        32        + len(event_losses)    )    loss_fraction = (        total_losses        / 49        * 100    )    print(        f"\nTotal event losses: "        f"{total_losses} / 49 "        f"({loss_fraction:.1f}%)"    )    print(        f"\nSummary saved to:\n"        f"{SUMMARY_OUTPUT_FILE}"    )def plot_altitude_and_kp(    daily,    summary,    kp,):    """    Plot Starlink orbital altitude trajectories and    geomagnetic Kp during the February 2022 event.    Event-loss satellites and event survivors are    plotted separately so their orbital behavior can    be compared.    """    # Add outcome information to every daily observation    plot_data = daily.merge(        summary[            [                "norad_id",                "event_outcome",            ]        ],        on="norad_id",        how="left",    )    # Figure 1 -->  satellite altitude trajectories       fig, ax = plt.subplots(        figsize=(11, 7)    )    # Plot satellites that survived the event    survived = plot_data[        plot_data["event_outcome"]        == "SURVIVED_EVENT"    ]    for norad_id, satellite in survived.groupby(        "norad_id"    ):        ax.plot(            satellite["date"],            satellite[                "daily_median_altitude_km"            ],            linewidth=1.5,            alpha=0.7,        )    # Plot satellites lost during the event    losses = plot_data[        plot_data["event_outcome"]        == "EVENT_LOSS"    ]    for norad_id, satellite in losses.groupby(        "norad_id"    ):        ax.plot(            satellite["date"],            satellite[                "daily_median_altitude_km"            ],            linewidth=2.5,            marker="o",            label=f"{norad_id} - event loss",        )    ax.set_title(        "Starlink Group 4-7 Orbital Evolution "        "During the February 2022 Event"    )    ax.set_xlabel(        "Date"    )    ax.set_ylabel(        "Approximate Mean Orbital Altitude (km)"    )    ax.grid(        alpha=0.3    )    ax.legend(        fontsize=8,        loc="best",    )    fig.autofmt_xdate()    plt.tight_layout()    altitude_file = (        RESULTS_DIR        / "starlink_2022_altitude_trajectories.png"    )    plt.savefig(        altitude_file,        dpi=300,        bbox_inches="tight",    )    plt.close()        # Figure 2 --> Kp timeline        fig, ax = plt.subplots(        figsize=(11, 4)    )    ax.plot(        kp["date"],        kp["daily_max_kp"],        marker="o",    )    # Kp = 5 storm threshold    ax.axhline(        y=5,        linestyle="--",        label="Kp = 5 storm threshold",    )    ax.set_title(        "Geomagnetic Activity During "        "Starlink Group 4-7 Event"    )    ax.set_xlabel(        "Date"    )    ax.set_ylabel(        "Daily Maximum Kp"    )    ax.set_ylim(        bottom=0    )    ax.grid(        alpha=0.3    )    ax.legend()    fig.autofmt_xdate()    plt.tight_layout()    kp_figure_file = (        RESULTS_DIR        / "starlink_2022_kp_timeline.png"    )    plt.savefig(        kp_figure_file,        dpi=300,        bbox_inches="tight",    )    plt.close()    print(        f"\nAltitude trajectory figure saved to:\n"        f"{altitude_file}"    )    print(        f"\nKp timeline figure saved to:\n"        f"{kp_figure_file}"    )# Maindef main():    records = (        load_orbital_history()    )    orbital_data = (        process_orbital_records(            records        )    )    daily_data = (        calculate_daily_altitudes(            orbital_data        )    )        kp_data = (        load_kp_data()    )        daily_data = (        merge_kp_with_altitude(            daily_data,            kp_data,        )    )        summary = (        summarize_satellites(            daily_data        )    )            satcat = (        load_satcat_data()    )        summary = (        add_event_outcomes(            summary,            satcat,        )    )        plot_altitude_and_kp(        daily_data,        summary,        kp_data,    )        print_event_summary(        summary    )if __name__ == "__main__":    main()